/*!50003 DROP PROCEDURE IF EXISTS `fill_Q2_stats` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`user`@`%` PROCEDURE `fill_Q2_stats`()
BEGIN
    DECLARE d DATE;
    DECLARE a INT;
    DECLARE b INT;

    -- Получаем последний (новый) тираж
    SELECT Tirage, n1, n2
    INTO d, a, b
    FROM Q2
    ORDER BY Tirage DESC
    LIMIT 1;

    -- Вставляем новую строку статистики (если ещё нет)
    INSERT IGNORE INTO Q2_stats (Tirage, n1, n2, days, days2, fois, max)
    SELECT 
        d,
        a,
        b,

        -- days
        IFNULL(DATEDIFF(d, (
            SELECT MAX(Tirage) FROM Q2
            WHERE Tirage < d AND n1 = a AND n2 = b
        )), 0),

        -- days2
        IFNULL(DATEDIFF((
            SELECT MAX(Tirage) FROM Q2
            WHERE Tirage < (
                SELECT MAX(Tirage) FROM Q2
                WHERE Tirage < d AND n1 = a AND n2 = b
            ) AND n1 = a AND n2 = b
        ), (
            SELECT MAX(Tirage) FROM Q2
            WHERE Tirage < d AND n1 = a AND n2 = b
        )), 0),

        -- fois
        IFNULL((
            SELECT COUNT(*) FROM Q2
            WHERE Tirage <= d AND n1 = a AND n2 = b
        ), 0),

        -- max
        IFNULL((
            SELECT MAX(DATEDIFF(Tirage, prev_Tirage)) FROM (
                SELECT Tirage,
                       LAG(Tirage) OVER (PARTITION BY n1, n2 ORDER BY Tirage) AS prev_Tirage
                FROM Q2
                WHERE n1 = a AND n2 = b AND Tirage <= d
            ) AS temp
            WHERE prev_Tirage IS NOT NULL
        ), 0);
END ;;
